const authType = env.get('AUTH_TYPE') || 'none';
const secret = env.get('WEBHOOK_SECRET') || '';

if (authType === 'none' || !secret) {
    return [msg, null];
}

if (authType === 'bearer') {
    const auth = msg.req.headers['authorization'] || '';
    if (auth === 'Bearer ' + secret) {
        return [msg, null];
    }
    msg.statusCode = 401;
    msg.payload = { message: 'unauthorized' };
    return [null, msg];
}

if (authType === 'hmac') {
    const crypto = global.get('crypto') || require('crypto');
    const header = (env.get('HMAC_HEADER') || 'x-webhook-signature').toLowerCase();
    const algorithm = env.get('HMAC_ALGORITHM') || 'sha256';
    const prefix = env.get('HMAC_PREFIX') || 'sha256=';
    const sigHeader = msg.req.headers[header] || '';
    if (prefix && !sigHeader.startsWith(prefix)) {
        msg.statusCode = 401;
        msg.payload = { message: 'unauthorized' };
        return [null, msg];
    }
    const rawBody = JSON.stringify(msg.req.body);
    const expected = prefix + crypto.createHmac(algorithm, secret).update(rawBody).digest('hex');
    const provided = Buffer.from(sigHeader);
    const computed = Buffer.from(expected);
    if (provided.length !== computed.length || !crypto.timingSafeEqual(provided, computed)) {
        msg.statusCode = 401;
        msg.payload = { message: 'unauthorized' };
        return [null, msg];
    }
    return [msg, null];
}

msg.statusCode = 500;
msg.payload = { message: 'unknown AUTH_TYPE: ' + authType };
return [null, msg];

