// Clean null/undefined values from fields
for (const route of routes) {
    for (const [key, val] of Object.entries(route.fields)) {
        if (val === undefined || val === null) delete route.fields[key];
    }
}

// Build response and route messages
const responseMsg = {
    payload: { message: routes.length > 0 ? 'accepted' : 'no matching routes', routes: routes.length },
    statusCode: 200,
    res: msg.res,
};

const routeMsgs = routes.map(route => ({ tulipRoute: route }));

return [responseMsg, routeMsgs];

const instanceUrl = env.get('TULIP_INSTANCE_URL').replace(/\/$/, '');
const apiKey = env.get('TULIP_API_KEY');
const apiSecret = env.get('TULIP_API_SECRET');
const workspace = env.get('TULIP_WORKSPACE');
const ws = workspace ? '/w/' + workspace : '';

const route = msg.tulipRoute;
const base = instanceUrl + '/api/v3' + ws + '/tables/' + route.tableId;
const auth = 'Basic ' + Buffer.from(apiKey + ':' + apiSecret).toString('base64');

msg._tulipAuth = auth;
msg._tulipBase = base;

if (route.mode === 'insert') {
    // Direct POST
    msg.url = base + '/records';
    msg.method = 'POST';
    msg.headers = { 'Authorization': auth, 'Content-Type': 'application/json' };
    msg.payload = Object.assign({ id: route.recordId }, route.fields);
    msg._tulipPhase = 'done';
    msg._tulipAction = 'created';
} else {
    // Upsert: start with GET
    msg.url = base + '/records/' + encodeURIComponent(route.recordId);
    msg.method = 'GET';
    msg.headers = { 'Authorization': auth, 'Content-Type': 'application/json' };
    msg._tulipPhase = 'get';
}

return msg;

const route = msg.tulipRoute;
const status = msg.statusCode;
const phase = msg._tulipPhase;

// If we just completed a POST or PUT (insert or upsert final step), log and finish
if (phase === 'done') {
    if (status >= 200 && status < 300) {
        node.log('Tulip ' + msg._tulipAction + ': ' + route.name + ' / ' + route.recordId);
    } else {
        node.error('Tulip ' + msg._tulipAction + ' failed (' + status + '): ' + route.name + ' / ' + route.recordId);
    }
    return null; // end of chain
}

// Phase was 'get' — decide to PUT or POST
if (phase === 'get') {
    if (status === 200) {
        // Record exists — PUT (Tulip Tables API uses PUT, not PATCH)
        msg.url = msg._tulipBase + '/records/' + encodeURIComponent(route.recordId);
        msg.method = 'PUT';
        msg.headers = { 'Authorization': msg._tulipAuth, 'Content-Type': 'application/json' };
        msg.payload = route.fields;
        msg._tulipPhase = 'done';
        msg._tulipAction = 'updated';
        return msg;
    }
    if (status === 404) {
        // Record doesn't exist — POST
        msg.url = msg._tulipBase + '/records';
        msg.method = 'POST';
        msg.headers = { 'Authorization': msg._tulipAuth, 'Content-Type': 'application/json' };
        msg.payload = Object.assign({ id: route.recordId }, route.fields);
        msg._tulipPhase = 'done';
        msg._tulipAction = 'created';
        return msg;
    }
    node.error('Tulip GET failed (' + status + '): ' + route.name + ' / ' + route.recordId);
    return null;
}

return null;
